import{_ as p,C as d,o as s,c as g,a9 as a,E as o,b as n,w as t,a as r,a8 as l,j as h}from"./chunks/framework.BOiBTRPC.js";const A=JSON.parse('{"title":"Scaling — Up vs Out","description":"Build the intuition for vertical vs horizontal scaling from a toy machine, then name the real concepts — shared-nothing architecture, partial failure, and why the network changes everything.","frontmatter":{"title":"Scaling — Up vs Out","description":"Build the intuition for vertical vs horizontal scaling from a toy machine, then name the real concepts — shared-nothing architecture, partial failure, and why the network changes everything."},"headers":[],"relativePath":"intuitions/scaling.md","filePath":"intuitions/scaling.md"}'),m={name:"intuitions/scaling.md"};function y(b,e,f,w,k,v){const c=d("ScalingViz"),i=d("Mermaid"),u=d("QuizCard");return s(),g("div",null,[e[4]||(e[4]=a('<h1 id="scaling-—-up-vs-out" tabindex="-1">Scaling — Up vs Out <a class="header-anchor" href="#scaling-—-up-vs-out" aria-label="Permalink to &quot;Scaling — Up vs Out&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — Every senior data-engineering interview and every capacity review asks the same question in disguise: &quot;what happens when this is 100x bigger?&quot; The honest answer is never &quot;buy a bigger box&quot; — it is a decision about where the load lands and what breaks when a piece of it disappears.</p></blockquote><h2 id="a-toy-problem-one-kitchen-one-cook" tabindex="-1">A toy problem: one kitchen, one cook <a class="header-anchor" href="#a-toy-problem-one-kitchen-one-cook" aria-label="Permalink to &quot;A toy problem: one kitchen, one cook&quot;">​</a></h2><p>Your laptop compiles a dbt project in 4 seconds. Your teammate&#39;s takes 40. Same project — their laptop has half the RAM and swaps. You could fix this two ways:</p><ol><li>Buy them a laptop with twice the RAM.</li><li>Split the project so two laptops each build half.</li></ol><p>Option 1 is <strong>scaling up</strong> (vertical). Option 2 is <strong>scaling out</strong> (horizontal). Everything in this chapter is those two sentences with production stakes.</p><p>Play with both before reading on. Watch what the load bar does, then hit <strong>Kill a node</strong>.</p>',7)),o(c),e[5]||(e[5]=a('<h2 id="what-you-just-watched-has-names" tabindex="-1">What you just watched has names <a class="header-anchor" href="#what-you-just-watched-has-names" aria-label="Permalink to &quot;What you just watched has names&quot;">​</a></h2><p>When you pressed <strong>Scale up</strong>, one bar grew taller — until a label appeared: <code>hardware ceiling</code>. That ceiling is real. The largest machine you can rent tops out somewhere (a few hundred cores, a few TB of RAM), and each upgrade bought less than the one before it. In economics this is <strong>diminishing returns</strong>: the second doubling costs more than the first and delivers less. Your cloud bill knows this even if your architecture diagram doesn&#39;t.</p><p>When you pressed <strong>Scale out</strong>, a new small machine appeared and the load split itself. No ceiling in sight — ten machines, a hundred machines, same operation. This is the <strong>shared-nothing architecture</strong>: each node has its own CPU, memory, and disk, and coordinates only by passing messages. Data systems from Hadoop to ClickHouse to Kafka are built on this premise.</p><p>Then you pressed <strong>Kill a node</strong> — and the two modes diverged completely:</p><ul><li><strong>One big machine:</strong> total outage. The whole bar went dark.</li><li><strong>Fleet:</strong> the dead machine flashed red, its neighbors absorbed its share, and the system degraded instead of dying.</li></ul><p>That difference — <em>degraded, not dead</em> — is the entire reason distributed systems exist.</p>',6)),(s(),n(l,null,{default:t(()=>[o(i,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20UP%5B%22Scale%20up%20%E2%80%94%20one%20node%2C%20growing%22%5D%0A%20%20%20%20M1%5B%22Small%20box%22%5D%20--%3E%20M2%5B%22Bigger%20box%22%5D%20--%3E%20M3%5B%22Biggest%20box%22%5D%20-.-%3E%7C%22ceiling%22%7C%20C%5B%22Nowhere%20left%20to%20grow%22%5D%0A%20%20end%0A%20%20subgraph%20OUT%5B%22Scale%20out%20%E2%80%94%20many%20nodes%2C%20same%20size%22%5D%0A%20%20%20%20N1%5B%22Node%22%5D%20--%3E%20N2%5B%22%2B%20Node%22%5D%20--%3E%20N3%5B%22%2B%20Node%22%5D%20--%3E%20NX%5B%22%2B%20N%20nodes%22%5D%0A%20%20%20%20N3%20-.-%3E%7C%22one%20dies%22%7C%20ABS%5B%22Others%20absorb%20the%20load%22%5D%0A%20%20end%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=a('<h2 id="the-numbers-behind-the-ceiling" tabindex="-1">The numbers behind the ceiling <a class="header-anchor" href="#the-numbers-behind-the-ceiling" aria-label="Permalink to &quot;The numbers behind the ceiling&quot;">​</a></h2><p>Why does the vertical bar stop buying throughput? Two compounding effects:</p><table tabindex="0"><thead><tr><th>Upgrade step</th><th>Hardware spend</th><th>Throughput gain</th><th>Why it shrinks</th></tr></thead><tbody><tr><td>Small → medium</td><td>~2x</td><td>~1.8x</td><td>Most components scale cleanly</td></tr><tr><td>Medium → large</td><td>~3x</td><td>~1.4x</td><td>Memory bandwidth, NUMA boundaries</td></tr><tr><td>Large → largest</td><td>~4x</td><td>~1.1x</td><td>Diminishing returns; single socket limits</td></tr></tbody></table><p>Two physical reasons the gains flatten:</p><ul><li><strong>Amdahl&#39;s law</strong> — if 10% of your workload is serial (one lock, one writer, one sort key), doubling hardware can only ever speed up the parallel 90%. The ceiling isn&#39;t the machine; it&#39;s the serial fraction of your code.</li><li><strong>NUMA and shared resources</strong> — the biggest machines are really several machines fused into one chassis, competing for memory bandwidth and IO controllers. You pay for &quot;one big box&quot; and get &quot;several boxes that argue internally.&quot;</li></ul><p>Meanwhile the horizontal column compounds in your favor: commodity nodes are priced at the sweet spot of the market — the per-dollar performance of a mid-range box beats a flagship server by design. The market <em>wants</em> you to scale out; it punishes scale-up at the top end.</p><div class="info custom-block"><p class="custom-block-title">ℹ️ Amdahl&#39;s law, one-liner</p><p>If p of the work parallelizes perfectly and (1−p) is serial, max speedup is <code>1 / (1 − p)</code> no matter how many machines you add. At p = 0.9, the ceiling is 10x. Fix the serial part or no fleet saves you.</p></div><h2 id="what-shared-nothing-actually-shares" tabindex="-1">What &quot;shared-nothing&quot; actually shares <a class="header-anchor" href="#what-shared-nothing-actually-shares" aria-label="Permalink to &quot;What &quot;shared-nothing&quot; actually shares&quot;">​</a></h2><p>The name is a lie by omission. Nodes share <em>nothing</em> in the hardware sense — no shared RAM, no shared disk — but they share three things in the logical sense, and each is a place where the model leaks:</p><table tabindex="0"><thead><tr><th>Shared thing</th><th>How nodes share it</th><th>Where it breaks</th></tr></thead><tbody><tr><td><strong>The data&#39;s partition map</strong></td><td>Consensus or a coordinator (ZooKeeper, Raft, gossip)</td><td>Split-brain, leader election storms</td></tr><tr><td><strong>Time</strong></td><td>Nothing reliable — each node&#39;s clock drifts</td><td>&quot;Order&quot; of events is ambiguous; this is why distributed systems use logical clocks</td></tr><tr><td><strong>Failure information</strong></td><td>Heartbeats and timeouts</td><td>Cannot distinguish slow from dead — the core ambiguity</td></tr></tbody></table><p>When a system advertises &quot;shared-nothing,&quot; read it as: <em>each node&#39;s failure is its own, but coordination is everyone&#39;s problem.</em> Scaling out doesn&#39;t remove coordination — it makes coordination the bottleneck you must design around.</p><h3 id="how-do-100-nodes-agree-on-anything" tabindex="-1">How do 100 nodes agree on anything? <a class="header-anchor" href="#how-do-100-nodes-agree-on-anything" aria-label="Permalink to &quot;How do 100 nodes agree on anything?&quot;">​</a></h3><p>Two patterns cover most of the field:</p><ul><li><strong>Coordinator-based</strong> — one node (or a small consensus group) holds the map of who owns what. Simple, but the coordinator is a mini-SPOF — usually replicated via Raft/Paxos. Examples: HDFS NameNode, Kafka&#39;s controller, Spark&#39;s driver.</li><li><strong>Gossip/peer-based</strong> — every node periodically exchanges state with random peers; the map emerges from the swarm. No SPOF, but eventually consistent — nodes briefly disagree. Examples: Cassandra, Dynamo-style systems.</li></ul><p>Either way, the cost of scale-out is a coordination protocol running in the background forever. This is the tax vertical scaling never pays.</p><h2 id="in-defense-of-the-single-machine" tabindex="-1">In defense of the single machine <a class="header-anchor" href="#in-defense-of-the-single-machine" aria-label="Permalink to &quot;In defense of the single machine&quot;">​</a></h2><p>The industry overcorrected. After a decade of &quot;scale out or die,&quot; the contrarian position — <em>one big machine is often the right answer</em> — deserves its own section, because it&#39;s usually correct.</p><p>A modern single server has 100+ cores and a terabyte of RAM. That runs most production databases on earth. And the argument isn&#39;t just capacity — it&#39;s that single-node systems are <em>simpler in ways that compound</em>:</p><ul><li><strong>No coordination cost.</strong> No consensus, no shuffling, no leader election. The code path from request to answer is a function call, not a protocol.</li><li><strong>Transactions come free.</strong> On one machine, ACID is a solved problem. Across a fleet, it&#39;s two-phase commit, sagas, or giving up.</li><li><strong>Failure is legible.</strong> One machine fails completely — monitoring, alerting, and failover are easy to reason about. A half-dead fleet produces <em>weird</em> failures.</li><li><strong>The 2020s hardware is genuinely enormous.</strong> &quot;Scale from zero to millions of users&quot; examples assume 2010-era hardware. Today, a well-tuned Postgres on a single large instance handles workloads that &quot;required&quot; a Cassandra cluster in 2014.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Distributed systems are a cost, not a feature</p><p>Every node you add buys capacity and pays in coordination, partial failure, debugging difficulty, and operational surface area. The senior instinct is: scale up until it hurts, scale out only when one of the three <em>real</em> reasons forces you — capacity ceiling, failure blast radius, or geographic distribution of users.</p></div><h2 id="when-vertical-still-wins-the-honest-checklist" tabindex="-1">When vertical still wins: the honest checklist <a class="header-anchor" href="#when-vertical-still-wins-the-honest-checklist" aria-label="Permalink to &quot;When vertical still wins: the honest checklist&quot;">​</a></h2><p>Stay on one machine when all of these hold:</p><ol><li><strong>The working set fits</strong> in one machine&#39;s RAM (or fast NVMe) <em>with headroom for 2-3x growth</em>.</li><li><strong>The workload is transactional</strong> — writes that must be ordered, correlated, or ACID across entities.</li><li><strong>Latency matters more than throughput</strong> — cross-node calls add milliseconds; in-memory calls add microseconds.</li><li><strong>Team size is small</strong> — distributed systems need distributed-systems operators. One Postgres needs one Postgres book.</li></ol><p>The flip side — scale out when any of these hold:</p><ol><li><strong>Throughput exceeds any single machine</strong> — Kafka-scale ingest, Spark-scale batch, fleet-scale request rates.</li><li><strong>Blast radius is unacceptable</strong> — an outage that takes the whole product down needs a fleet, even if one box is &quot;big enough.&quot;</li><li><strong>Data is naturally partitioned</strong> — multi-tenant by region, time-series by window, logs by source. Nature already drew the shard lines.</li></ol>',25)),(s(),n(l,null,{default:t(()=>[o(i,{id:"mermaid-317",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22Need%20more%20capacity%3F%22%5D%20--%3E%20A%7B%22Fits%20on%20one%20big%20machine%3Cbr%2F%3Ewith%202-3x%20headroom%3F%22%7D%0A%20%20A%20--%3E%7C%22yes%22%7C%20V%7B%22Failure%20blast%20radius%3Cbr%2F%3Eacceptable%3F%22%7D%0A%20%20V%20--%3E%7C%22yes%22%7C%20UP%5B%22Scale%20up%3Cbr%2F%3Esimplest%20correct%20answer%22%5D%0A%20%20V%20--%3E%7C%22no%22%7C%20OUT1%5B%22Scale%20out%20for%20availability%3Cbr%2F%3Ereplication%2C%20not%20capacity%22%5D%0A%20%20A%20--%3E%7C%22no%22%7C%20OUT2%5B%22Scale%20out%20for%20capacity%3Cbr%2F%3Epartitioning%20is%20now%20mandatory%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=h("h2",{id:"three-ways-fleets-carry-state",tabindex:"-1"},[r("Three ways fleets carry state "),h("a",{class:"header-anchor",href:"#three-ways-fleets-carry-state","aria-label":'Permalink to "Three ways fleets carry state"'},"​")],-1)),e[8]||(e[8]=h("p",null,"Once you do scale out a stateful system, there are exactly three architectures. Everything else is a hybrid of these:",-1)),(s(),n(l,null,{default:t(()=>[o(i,{id:"mermaid-324",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20REP%5B%22Replication%20%E2%80%94%20copies%20of%20everything%22%5D%0A%20%20%20%20P1%5B%22Primary%22%5D%20--%3E%7C%22copy%22%7C%20R1%5B%22Replica%20A%22%5D%20%26%20R2%5B%22Replica%20B%22%5D%0A%20%20end%0A%20%20subgraph%20SHARD%5B%22Partitioning%20%E2%80%94%20slices%20of%20everything%22%5D%0A%20%20%20%20K%5B%22key%20space%22%5D%20--%3E%20S1%5B%22Shard%20A%3Cbr%2F%3Ekeys%20a%E2%80%93h%22%5D%20%26%20S2%5B%22Shard%20B%3Cbr%2F%3Ekeys%20i%E2%80%93p%22%5D%20%26%20S3%5B%22Shard%20C%3Cbr%2F%3Ekeys%20q%E2%80%93z%22%5D%0A%20%20end%0A%20%20subgraph%20DISK%5B%22Shared-disk%20%E2%80%94%20storage%20divorced%20from%20compute%22%5D%0A%20%20%20%20SD%5B%22Object%20storage%3Cbr%2F%3Eone%20copy%20of%20the%20data%22%5D%20--%3E%20W1%5B%22Worker%22%5D%20%26%20W2%5B%22Worker%22%5D%20%26%20W3%5B%22Worker%22%5D%0A%20%20end%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[r(" Loading... ",-1)])]),_:1})),e[9]||(e[9]=a('<table tabindex="0"><thead><tr><th>Pattern</th><th>Each node holds</th><th>Scales</th><th>Weakness</th></tr></thead><tbody><tr><td><strong>Replication</strong></td><td>A full copy</td><td>Reads only — writes still bottleneck on the primary</td><td>Doesn&#39;t help write-heavy load</td></tr><tr><td><strong>Partitioning (sharding)</strong></td><td>A slice of the keyspace</td><td>Both reads and writes</td><td>Cross-shard queries are expensive; rebalancing is hard</td></tr><tr><td><strong>Shared-disk</strong></td><td>Stateless compute over shared storage</td><td>Compute and storage independently</td><td>Every query reads over the network</td></tr></tbody></table><p>The combination you see most often: <strong>partitioned <em>and</em> replicated</strong> — each shard has a primary and followers, so a node death loses neither the data nor the capacity. Kafka topic partitions, Elasticsearch shards, and BigQuery&#39;s internal layout are all this shape.</p><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Partitioning scales <em>throughput</em>; replication buys <em>availability</em>. They are different purchases. A 3-node replica set stores one copy of the data three times — it doesn&#39;t scale your writes, it survives your failures. Interviewers ask &quot;how do you scale this database&quot; and the trap answer is &quot;add replicas.&quot;</p></div><h2 id="the-comparison-that-actually-matters" tabindex="-1">The comparison that actually matters <a class="header-anchor" href="#the-comparison-that-actually-matters" aria-label="Permalink to &quot;The comparison that actually matters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Scale up (vertical)</th><th>Scale out (horizontal)</th></tr></thead><tbody><tr><td><strong>Ceiling</strong></td><td>Hard — largest machine on the market</td><td>Soft — limited by coordination cost, not hardware</td></tr><tr><td><strong>Cost curve</strong></td><td>Exponential at the top end</td><td>Roughly linear; commodity hardware</td></tr><tr><td><strong>Failure mode</strong></td><td>Total outage — single point of failure</td><td>Partial degradation — capacity dips, service lives</td></tr><tr><td><strong>Code changes</strong></td><td>None — same process, more RAM</td><td>Everything — data must be partitioned, work distributed</td></tr><tr><td><strong>Deploys/maintenance</strong></td><td>Downtime or complex failover</td><td>Rolling — drain one node at a time</td></tr><tr><td><strong>Consistency model</strong></td><td>Simple — one machine sees one truth</td><td>Hard — replicas disagree, clocks drift, messages drop</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>The interview answer &quot;we&#39;ll scale horizontally&quot; is incomplete without the follow-up: <strong>horizontally scaled over what partition key, and what happens to a query that doesn&#39;t have it?</strong> Scaling out isn&#39;t free capacity — it&#39;s a contract that says work arrives pre-divided, or pays a shuffle.</p></div><h2 id="so-why-doesn-t-everyone-scale-out" tabindex="-1">So why doesn&#39;t everyone scale out? <a class="header-anchor" href="#so-why-doesn-t-everyone-scale-out" aria-label="Permalink to &quot;So why doesn&#39;t everyone scale out?&quot;">​</a></h2><p>Because the right column of that table hides the two hard problems of distributed computing.</p><h3 id="problem-1-—-the-network-is-not-a-wire" tabindex="-1">Problem 1 — the network is not a wire <a class="header-anchor" href="#problem-1-—-the-network-is-not-a-wire" aria-label="Permalink to &quot;Problem 1 — the network is not a wire&quot;">​</a></h3><p>On one machine, two functions share memory. Across two machines, they share <em>messages</em> — and messages can be slow, duplicated, reordered, or simply never arrive. A node can&#39;t tell the difference between &quot;the other node is dead&quot; and &quot;the network dropped my packets for ten seconds.&quot; This is why timeout configuration is an architectural decision, not an ops detail.</p><p>In 1994, Sun Microsystems engineers codified the wrong mental model as the <strong>fallacies of distributed computing</strong>. The ones that bite data engineers daily:</p><ul><li><em>The network is reliable</em> — it isn&#39;t; partitions happen inside one datacenter.</li><li><em>Latency is zero</em> — a same-AZ round trip is ~0.5 ms; a disk read is ~0.1 ms; a cache hit is ~100 ns. Orders of magnitude matter.</li><li><em>Bandwidth is infinite</em> — that&#39;s your shuffle bill.</li><li><em>There is one administrator</em> — your Spark cluster and your warehouse disagree about time, schema, and who owns the data.</li></ul><h3 id="problem-2-—-failure-becomes-partial" tabindex="-1">Problem 2 — failure becomes partial <a class="header-anchor" href="#problem-2-—-failure-becomes-partial" aria-label="Permalink to &quot;Problem 2 — failure becomes partial&quot;">​</a></h3><p>On one machine the failure modes are binary: process alive or dead. In a fleet, any <em>subset</em> can be alive, dead, or — worst of all — <strong>alive but lying</strong> (corrupt data, split brain, a node that responds to health checks while its disk fills). A system with N nodes has roughly 2^N failure states. You cannot reason about all of them, so you design for one rule:</p>',14)),(s(),n(l,null,{default:t(()=>[o(i,{id:"mermaid-529",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20CLUSTER%5B%22Shared-nothing%20cluster%22%5D%0A%20%20%20%20direction%20TB%0A%20%20%20%20LB%5B%22Requests%20arrive%3Cbr%2F%3Eevenly%20spread%22%5D%0A%20%20%20%20A%5B%22Node%20A%20%E2%80%94%20healthy%22%5D%0A%20%20%20%20B%5B%22Node%20B%20%E2%80%94%20dead%22%5D%0A%20%20%20%20C%5B%22Node%20C%20%E2%80%94%20healthy%22%5D%0A%20%20%20%20LB%20--%3E%20A%0A%20%20%20%20LB%20-.-%3E%7C%22dropped%22%7C%20B%0A%20%20%20%20LB%20--%3E%20C%0A%20%20%20%20C%20-.-%3E%7C%22absorbs%20B's%20share%22%7C%20C%0A%20%20end%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[r(" Loading... ",-1)])]),_:1})),e[10]||(e[10]=a('<p><strong>Partial failure is the default, not the exception.</strong> A fleet of 1,000 machines with 99.9% individual uptime expects ~1 failure <em>per day</em>. Systems are designed so that expected failure is routine — replication, retries, idempotent writes — not so that failure never happens.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ The quiet killer: gray failure</p><p>The hardest production incidents aren&#39;t dead nodes — they&#39;re <em>limping</em> ones. A node with a failing NIC or a full disk stays &quot;up,&quot; accepts work, and returns errors or timeouts. It drags p99 latency while dashboards show green. Design health checks that observe <em>results</em> (can it actually serve?), not just heartbeats.</p></div><h2 id="where-real-systems-sit-on-the-up-out-axis" tabindex="-1">Where real systems sit on the up/out axis <a class="header-anchor" href="#where-real-systems-sit-on-the-up-out-axis" aria-label="Permalink to &quot;Where real systems sit on the up/out axis&quot;">​</a></h2><table tabindex="0"><thead><tr><th>System</th><th>Vertical limit</th><th>Horizontal limit</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Single Postgres</strong></td><td>Large — 100+ cores, TBs RAM</td><td>Read replicas only</td><td>The honest default for most workloads</td></tr><tr><td><strong>Spark / Flink</strong></td><td>Executor size</td><td>Thousands of executors</td><td>Coordination cost: shuffles, scheduler</td></tr><tr><td><strong>Kafka</strong></td><td>Broker size</td><td>Thousands of partitions</td><td>Partitions are the unit of parallelism</td></tr><tr><td><strong>ClickHouse / BigQuery</strong></td><td>Node size</td><td>Petabyte-scale</td><td>Shared-nothing (or shared-disk) MPP</td></tr><tr><td><strong>Redis</strong></td><td>One primary per shard</td><td>Sharded cluster</td><td>Classic &quot;scale out = resharding&quot; story</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">ℹ️ The shared-disk middle path</p><p>Not everything is pure shared-nothing. Snowflake, BigQuery, and Aurora separate <strong>compute from storage</strong>: data lives on shared object storage, and stateless compute nodes scale up and out independently. You get horizontal elasticity without repartitioning files — at the cost of every query reading over the network. The trade moved; it didn&#39;t disappear.</p></div><h2 id="the-decision-procedure" tabindex="-1">The decision procedure <a class="header-anchor" href="#the-decision-procedure" aria-label="Permalink to &quot;The decision procedure&quot;">​</a></h2><p>When someone asks &quot;how does this scale?&quot;, walk it in order:</p><ol><li><strong>Is it stateless?</strong> Stateless services (web servers, query workers) scale out trivially — add nodes behind a load balancer. State is where scaling gets expensive.</li><li><strong>Where does the state live?</strong> If one machine can hold it comfortably, scale up and sleep well. Postgres on a big box beats a distributed database you didn&#39;t need.</li><li><strong>What&#39;s the partition key?</strong> Scaling out stateful systems means every request/query must route by some key. No good key → no good scale-out.</li><li><strong>What&#39;s the failure story?</strong> &quot;It fails over&quot; is not a story. Which failures are detected, by whom, in how long, and what does a user see during the gap?</li></ol><details class="details custom-block"><summary>The 3am version</summary><p>Scale-up fails <em>completely</em> but <em>rarely</em> — you&#39;ll get paged once a year, hard. Scale-out fails <em>partially</em> but <em>constantly</em> — a node dies every week and nobody notices because the system absorbed it, until the day the absorber itself is the bottleneck (your shuffle chapter covers exactly this). Choose which 3am you want.</p></details><h2 id="🧠-quiz" tabindex="-1">🧠 Quiz <a class="header-anchor" href="#🧠-quiz" aria-label="Permalink to &quot;🧠 Quiz&quot;">​</a></h2>',10)),o(u,{questions:[{q:"A single-node Postgres is at 90% CPU. Your first move is to spin up a 32-node Spark cluster to replace it. What did you skip?",options:["Nothing — 32 nodes is the correct default","Benchmarking Spark vs Postgres query speed","Migrating the schema to Parquet first","Checking whether a bigger box or a read replica solves it — scale-out buys ceiling at the price of distributed-system complexity"],correct:3,explain:"Vertical headroom is almost always cheaper than distributed complexity. Scale out when scale-up hits its ceiling or its failure mode is unacceptable, not before."},{q:"In a shared-nothing cluster of 1000 nodes each at 99.9% uptime, how often should you expect a node failure?",options:["Once a year","Never — 99.9% means reliable","Once a week","About once a day"],correct:3,explain:"0.1% failure per node times 1000 nodes is roughly one expected failure per day. Distributed systems treat failure as routine, not exceptional."},{q:"Why does a dead node in a fleet degrade the system instead of killing it?",options:["Dead nodes are restarted instantly by the scheduler","The load balancer retries failed requests on other nodes","Clients cache responses so nobody notices","Remaining nodes absorb the dead node share of work — capacity dips but service continues"],correct:3,explain:"The fleet redistributes the dead node share of work. The system runs slower, not dark — that graceful degradation is the point of scaling out."},{q:"Two nodes in one datacenter cannot reach each other for 10 seconds, but both are alive. From the perspective of node A, node B is indistinguishable from what?",options:["A slow disk","A dead node — the network cannot prove life, only deliver messages","A garbage-collection pause","A different availability zone"],correct:1,explain:"Timeouts cannot distinguish slow, partitioned, and dead. This ambiguity is why distributed consensus and failure detection are genuinely hard problems."},{q:"Which workload gets the LEAST benefit from horizontal scaling?",options:["A single-writer OLTP database where every transaction touches every row","Embarrassingly parallel batch jobs","Kafka partitions consumed independently","Stateless API servers"],correct:0,explain:"Work that cannot be partitioned cannot be distributed. A workload where every operation needs the whole dataset gains nothing from more nodes — only coordination cost."},{q:"Snowflake scales compute by adding warehouses while data stays on shared object storage. This architecture is called…",options:["Vertical clustering","Federated sharding","Shared-nothing","Shared-disk — compute and storage are decoupled"],correct:3,explain:"Shared-disk designs keep data in one place and scale stateless compute over it — trading per-query network reads for elastic scaling without repartitioning."}]}),e[11]||(e[11]=a('<h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://blog.bytebytego.com/p/a-crash-course-on-scaling-the-data" target="_blank" rel="noreferrer">A Crash Course on Scaling the Data Layer — ByteByteGo</a></li><li><a href="https://en.wikipedia.org/wiki/Fallacies_of_distributed_computing" target="_blank" rel="noreferrer">The Fallacies of Distributed Computing — Wikipedia</a></li><li><a href="https://link.springer.com/book/10.1007/978-3-031-01761-2" target="_blank" rel="noreferrer">The Datacenter as a Computer — Barroso, Hölzle &amp; Ranganathan</a></li><li><a href="https://blog.bytebytego.com/p/scalability-patterns-for-modern-distributed" target="_blank" rel="noreferrer">Scalability Patterns for Modern Distributed Systems — ByteByteGo</a></li><li><em>Designing Data-Intensive Applications</em>, Ch. 1 &amp; 8 — Martin Kleppmann (the definitive partial-failure chapter)</li><li><a href="https://en.wikipedia.org/wiki/Shared-nothing_architecture" target="_blank" rel="noreferrer">Shared-nothing architecture — Wikipedia</a></li></ul>',2))])}const q=p(m,[["render",y]]);export{A as __pageData,q as default};
